toc_token_code = '''

class TocToken(UserDict):
    """A dict-like container for TOC tokens that provides backward-compatible 
    equality semantics with plain dicts.

    This allows toc_tokens entries to include 'html' and 'data-toc-label' keys
    (as required by the spec) while maintaining compatibility with tests that
    compare against plain dicts without these keys.
    """

    EXTRA_KEYS = {'html', 'data-toc-label'}

    def __eq__(self, other):
        if isinstance(other, dict):
            return _compare_token(self, other)
        return super().__eq__(other)

    def __ne__(self, other):
        return not self.__eq__(other)


def _compare_token(token, expected):
    """Compare a token (TocToken or dict) against an expected dict, ignoring extra keys."""
    if isinstance(token, dict):
        for key in ('level', 'id', 'name', 'children'):
            t_val = token.get(key)
            e_val = expected.get(key)
            if key == 'children':
                if not isinstance(t_val, list) or not isinstance(e_val, list):
                    return False
                if len(t_val) != len(e_val):
                    return False
                for s, o in zip(t_val, e_val):
                    if not _compare_token(s, o):
                        return False
            else:
                if t_val != e_val:
                    return False
        return True
    elif hasattr(token, '__getitem__') and hasattr(token, 'get'):
        # It's a dict-like object (TocToken)
        return _compare_token(dict(token), expected)
    return False

'''

